profiles Penzias and Wilson''s careers."}, {"id": "C", "text": "It describes the CMB, recounts its discovery, and explains its origin in the early universe."}, {"id": "D", "text": "It argues that the Big Bang never happened."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Cosmic microwave background", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Cosmic_microwave_background', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M30-TS009', 'C', ARRAY['C']::TEXT[], 'The passage moves from description to discovery and then to cosmological explanation.', '{"B": "The discoverers are named, not profiled.", "A": "Radio broadcasts are not discussed.", "D": "The text presents the CMB as evidence for the Big Bang."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
